import React, { useCallback, useEffect, useMemo, useRef, useState } from "react";

type RawMaterial =
  | string
  | {
      id?: string | number;
      name?: string;
      filename?: string;
      file_name?: string;
      basename?: string;
      path?: string;
      url?: string;
      size?: number | string;
      size_bytes?: number | string;
      bytes?: number | string;
      type?: string;
      mime?: string;
      mime_type?: string;
      content_type?: string;
      extension?: string;
      ext?: string;
      modified_at?: string;
      updated_at?: string;
      created_at?: string;
    };

type MaterialsApiResponse =
  | RawMaterial[]
  | {
      materials?: RawMaterial[];
      files?: RawMaterial[];
      items?: RawMaterial[];
      data?: RawMaterial[];
      total?: number;
    };

type MaterialItem = {
  id: string;
  name: string;
  path?: string;
  sizeBytes: number;
  typeLabel: string;
  typeKey: "image" | "video" | "audio" | "document" | "archive" | "code" | "unknown";
  extension: string;
  modifiedAt?: string;
};

const MATERIALS_API = "/api/materials";

function getArrayFromResponse(payload: MaterialsApiResponse): RawMaterial[] {
  if (Array.isArray(payload)) return payload;
  if (Array.isArray(payload.materials)) return payload.materials;
  if (Array.isArray(payload.files)) return payload.files;
  if (Array.isArray(payload.items)) return payload.items;
  if (Array.isArray(payload.data)) return payload.data;
  return [];
}

function getBaseName(value: string): string {
  const normalized = value.replaceAll("\\", "/");
  const parts = normalized.split("/").filter(Boolean);
  return parts.at(-1) || value;
}

function toNumber(value: number | string | undefined): number {
  if (typeof value === "number" && Number.isFinite(value)) return value;
  if (typeof value === "string") {
    const parsed = Number(value);
    if (Number.isFinite(parsed)) return parsed;
  }
  return 0;
}

function getExtensionFromName(name: string): string {
  const clean = name.split("?")[0]?.split("#")[0] || name;
  const lastDot = clean.lastIndexOf(".");
  if (lastDot < 0 || lastDot === clean.length - 1) return "";
  return clean.slice(lastDot + 1).toLowerCase();
}

function formatBytes(bytes: number): string {
  if (!bytes || bytes <= 0) return "0 B";

  const units = ["B", "KB", "MB", "GB", "TB"];
  let value = bytes;
  let unitIndex = 0;

  while (value >= 1024 && unitIndex < units.length - 1) {
    value /= 1024;
    unitIndex += 1;
  }

  const precision = value >= 10 || unitIndex === 0 ? 0 : 1;
  return `${value.toFixed(precision)} ${units[unitIndex]}`;
}

function inferMaterialType(
  extension: string,
  mimeLike?: string
): {
  typeKey: MaterialItem["typeKey"];
  typeLabel: string;
} {
  const mime = (mimeLike || "").toLowerCase();
  const ext = extension.toLowerCase();

  if (
    mime.startsWith("image/") ||
    ["jpg", "jpeg", "png", "webp", "gif", "svg", "bmp", "avif", "heic"].includes(ext)
  ) {
    return { typeKey: "image", typeLabel: "图片素材" };
  }

  if (
    mime.startsWith("video/") ||
    ["mp4", "mov", "m4v", "avi", "mkv", "webm", "flv"].includes(ext)
  ) {
    return { typeKey: "video", typeLabel: "视频素材" };
  }

  if (
    mime.startsWith("audio/") ||
    ["mp3", "wav", "aac", "m4a", "flac", "ogg"].includes(ext)
  ) {
    return { typeKey: "audio", typeLabel: "音频素材" };
  }

  if (
    ["txt", "md", "json", "csv", "xlsx", "xls", "doc", "docx", "pdf", "ppt", "pptx"].includes(ext)
  ) {
    return { typeKey: "document", typeLabel: "文档素材" };
  }

  if (["zip", "rar", "7z", "tar", "gz"].includes(ext)) {
    return { typeKey: "archive", typeLabel: "压缩包" };
  }

  if (["js", "ts", "tsx", "jsx", "py", "html", "css", "scss", "yaml", "yml"].includes(ext)) {
    return { typeKey: "code", typeLabel: "代码文件" };
  }

  return { typeKey: "unknown", typeLabel: "未知类型" };
}

function normalizeMaterial(raw: RawMaterial, index: number): MaterialItem {
  if (typeof raw === "string") {
    const name = getBaseName(raw);
    const extension = getExtensionFromName(name);
    const inferred = inferMaterialType(extension);

    return {
      id: `${raw}-${index}`,
      name,
      path: raw,
      sizeBytes: 0,
      extension: extension || "unknown",
      ...inferred,
    };
  }

  const rawName =
    raw.name ||
    raw.filename ||
    raw.file_name ||
    raw.basename ||
    raw.path ||
    raw.url ||
    `material-${index + 1}`;

  const name = getBaseName(String(rawName));
  const extension = (raw.extension || raw.ext || getExtensionFromName(name) || "unknown").toString();
  const mimeLike = raw.mime || raw.mime_type || raw.content_type || raw.type;
  const inferred = inferMaterialType(extension, mimeLike);

  return {
    id: String(raw.id || raw.path || raw.url || name || index),
    name,
    path: raw.path || raw.url,
    sizeBytes: toNumber(raw.size_bytes ?? raw.bytes ?? raw.size),
    extension: extension.toLowerCase(),
    modifiedAt: raw.modified_at || raw.updated_at || raw.created_at,
    ...inferred,
  };
}

function getTypeBadgeClass(typeKey: MaterialItem["typeKey"]): string {
