export default function HomePage() {
  const [materials, setMaterials] = useState<MaterialItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [lastLoadedAt, setLastLoadedAt] = useState<Date | null>(null);

  const abortRef = useRef<AbortController | null>(null);

  const loadMaterials = useCallback(async (silent = false) => {
    abortRef.current?.abort();

    const controller = new AbortController();
    abortRef.current = controller;

    try {
      if (silent) {
        setRefreshing(true);
      } else {
        setLoading(true);
      }

      setError(null);

      const response = await fetch(MATERIALS_API, {
        method: "GET",
        headers: {
          Accept: "application/json",
        },
        signal: controller.signal,
      });

      if (!response.ok) {
        throw new Error(`读取素材失败：HTTP ${response.status}`);
      }

      const payload = (await response.json()) as MaterialsApiResponse;
      const rawItems = getArrayFromResponse(payload);

      const normalized = rawItems
        .map((item, index) => normalizeMaterial(item, index))
        .sort((a, b) => a.name.localeCompare(b.name, "zh-Hans-CN"));

      setMaterials(normalized);
      setLastLoadedAt(new Date());
    } catch (err) {
      if (err instanceof DOMException && err.name === "AbortError") return;
      setError(err instanceof Error ? err.message : "读取 samples/ 目录失败");
      setMaterials([]);
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  }, []);

  useEffect(() => {
    loadMaterials(false);

    return () => {
      abortRef.current?.abort();
    };
  }, [loadMaterials]);

  const stats = useMemo(() => {
    const totalSize = materials.reduce((sum, item) => sum + item.sizeBytes, 0);
    const imageCount = materials.filter((item) => item.typeKey === "image").length;
    const videoCount = materials.filter((item) => item.typeKey === "video").length;
    const audioCount = materials.filter((item) => item.typeKey === "audio").length;

    return {
      totalFiles: materials.length,
      totalSize,
      imageCount,
      videoCount,
      audioCount,
    };
  }, [materials]);

  return (
    <main className="min-h-screen bg-[oklch(7%_0.006_95)] text-[oklch(88%_0_0)]">
      <div className="pointer-events-none fixed inset-0 overflow-hidden">
        <div className="absolute -left-44 top-[-6rem] h-[28rem] w-[28rem] rounded-full bg-[oklch(84%_0.19_80/0.12)] blur-3xl" />
        <div className="absolute bottom-[-10rem] right-[-6rem] h-[34rem] w-[34rem] rounded-full bg-[oklch(77%_0.13_82/0.10)] blur-3xl" />
        <div className="absolute inset-x-0 top-0 h-px bg-[linear-gradient(90deg,transparent,oklch(84%_0.19_80/0.45),transparent)]" />
      </div>

      <section className="relative mx-auto max-w-7xl px-6 py-8 lg:px-8">
        <header className="mb-8 flex flex-col gap-5 lg:flex-row lg:items-end lg:justify-between">
          <div>
            <div className="mb-3 inline-flex items-center gap-2 rounded-full border border-[oklch(84%_0.19_80/0.32)] bg-[oklch(84%_0.19_80/0.10)] px-3 py-1 text-xs font-medium text-[oklch(91%_0.06_84)]">
              <span className="h-1.5 w-1.5 rounded-full bg-[oklch(84%_0.19_80)] shadow-[0_0_18px_oklch(84%_0.19_80)]" />
              samples/ 真实素材目录
            </div>

            <h1 className="text-4xl font-semibold tracking-tight text-[oklch(91%_0_0)]">
              PHS 素材首页
            </h1>

            <p className="mt-3 max-w-2xl text-sm leading-6 text-[oklch(72%_0_0)]">
              从 <span className="font-medium text-[oklch(91%_0.06_84)]">GET /api/materials</span>{" "}
              读取真实素材文件，展示真实文件名、大小与类型。
            </p>
          </div>

          <div className="flex flex-wrap items-center gap-3">
            {lastLoadedAt ? (
              <div className="rounded-2xl border border-white/10 bg-white/5 px-4 py-3 text-xs text-[oklch(72%_0_0)]">
                最近同步：{lastLoadedAt.toLocaleTimeString()}
              </div>
            ) : null}

            <button
              type="button"
              onClick={() => loadMaterials(true)}
              disabled={loading || refreshing}
              className="rounded-2xl bg-[oklch(84%_0.19_80)] px-5 py-3 text-sm font-semibold text-[oklch(8%_0.006_95)] shadow-[0_16px_42px_oklch(84%_0.19_80/0.22)] transition hover:bg-[oklch(86%_0.07_84)] active:bg-[oklch(77%_0.13_82)] disabled:cursor-not-allowed disabled:opacity-50"
            >
              {refreshing ? "刷新中..." : "刷新素材"}
            </button>
          </div>
        </header>

        {error ? (
          <div className="mb-6 rounded-3xl border border-red-400/30 bg-red-400/10 px-5 py-4 text-sm text-red-100">
            {error}
          </div>
        ) : null}

        <div className="mb-6 grid grid-cols-1 gap-5 md:grid-cols-2 xl:grid-cols-5">
          <MetricCard label="真实文件数" value={stats.totalFiles} hint="来自 samples/ 目录" emphasis />
          <MetricCard label="总大小" value={formatBytes(stats.totalSize)} hint="按 API 返回 size 汇总" />
          <MetricCard label="图片素材" value={stats.imageCount} hint="jpg / png / webp 等" />
          <MetricCard label="视频素材" value={stats.videoCount} hint="mp4 / mov / webm 等" />
          <MetricCard label="音频素材" value={stats.audioCount} hint="mp3 / wav / m4a 等" />
        </div>

        <section className="rounded-[2rem] border border-[oklch(22%_0.018_95)] bg-[oklch(10%_0.006_95/0.82)] p-5 shadow-[0_24px_90px_rgba(0,0,0,0.28)] backdrop-blur">
          <div className="mb-5 flex flex-col gap-2 sm:flex-row sm:items-center sm:justify-between">
            <div>
              <h2 className="text-xl font-semibold tracking-tight text-[oklch(91%_0_0)]">
                真实素材文件
              </h2>
              <p className="mt-1 text-sm text-[oklch(72%_0_0)]">
                已移除硬编码 demo 数据，仅展示接口返回的真实文件。
              </p>
            </div>

            <div className="rounded-full border border-white/10 bg-black/20 px-3 py-1 text-xs text-[oklch(72%_0_0)]">
              {materials.length} files
            </div>
          </div>

          {loading ? (
            <LoadingSkeleton />
          ) : materials.length > 0 ? (
            <div className="grid grid-cols-1 gap-5 md:grid-cols-2 xl:grid-cols-3">
              {materials.map((item) => (
                <MaterialCard key={item.id} item={item} />
              ))}
            </div>
          ) : (
            <div className="flex min-h-[280px] flex-col items-center justify-center rounded-[1.75rem] border border-dashed border-[oklch(32%_0.018_95)] bg-black/20 px-6 text-center">
              <div className="flex h-16 w-16 items-center justify-center rounded-3xl border border-[oklch(84%_0.19_80/0.28)] bg-[oklch(84%_0.19_80/0.10)] text-sm font-black tracking-wider text-[oklch(91%_0.06_84)]">
                EMPTY
              </div>

              <h3 className="mt-5 text-lg font-semibold text-[oklch(91%_0_0)]">
                samples/ 暂无可展示素材
              </h3>

              <p className="mt-2 max-w-md text-sm leading-6 text-[oklch(72%_0_0)]">
                请确认后端 <span className="font-medium text-[oklch(91%_0.06_84)]">/api/materials</span>{" "}
                已正确扫描 samples/ 目录，并返回文件名、大小和类型字段。
              </p>
            </div>
          )}
        </section>
      </section>
    </main>
  );
}
